entries.syntax:
CREATE TABLE name (col1 TYPE, col2 TYPE, ...);

-- optional rules on a column
CREATE TABLE name (id INTEGER PRIMARY KEY, col TEXT NOT NULL);

entries.example:
CREATE TABLE holdings (ticker TEXT, price REAL, chg REAL);

-- prove it exists: sqlite keeps the list of tables in sqlite_master
SELECT name FROM sqlite_master WHERE type = 'table';

DROP TABLE IF EXISTS holdings;
CREATE TABLE holdings (ticker TEXT, price REAL, chg REAL);

SELECT COUNT(*) AS n_rows FROM holdings;

INSERT INTO holdings VALUES ('NVDA', 219.00, -3.42);
INSERT INTO holdings VALUES ('AAPL', 146.00, -2.73), ('GOOG', 2829.27, -58.20);

SELECT * FROM holdings;

SELECT passenger_id, sex, fare
FROM passengers
WHERE fare > 50;

SELECT passenger_id, fare
FROM passengers
ORDER BY fare DESC;

-- who has no recorded age?
SELECT passenger_id, age FROM passengers WHERE age IS NULL;

-- average age over the rows that do have one
SELECT ROUND(AVG(age), 1) AS avg_age FROM passengers WHERE age IS NOT NULL;

entries.syntax:
SELECT group_col, COUNT(*) AS n, AVG(value_col) AS avg_value
FROM table
GROUP BY group_col;

