entries.example:
SELECT p.passenger_id, p.embarked, o.port_name
FROM passengers AS p
INNER JOIN ports AS o
  ON p.embarked = o.embarked;

-- compare the row counts of the two join types
SELECT COUNT(*) AS n_inner FROM passengers AS p INNER JOIN ports AS o ON p.embarked = o.embarked;
SELECT COUNT(*) AS n_left  FROM passengers AS p LEFT JOIN  ports AS o ON p.embarked = o.embarked;

